"use client";

import Engine from "./image-fly-in-engine.jsx";
import css from "./image-fly-in-styles";

export interface FlyInImage {
  src: string;
  alt?: string;
  aspect?:
    | "portrait_sm"
    | "portrait_md"
    | "portrait_lg"
    | "landscape_sm"
    | "landscape_lg"
    | "square_sm"
    | "square_lg";
  hideMobile?: boolean;
}
export interface ImageFlyInProps {
  className?: string;
  images?: FlyInImage[];
  headline?: string;
  support?: string;
  duration?: number;
  depth?: number;
  speed?: number;
  scrollBoost?: number;
  pan?: number;
  holeBuffer?: number;
}

export function ImageFlyIn(props: ImageFlyInProps) {
  return (
    <>
      <style>{css}</style>
      <Engine {...props} />
    </>
  );
}

import type { ImageFlyInProps } from "./image-fly-in";
import type { ComponentType } from "react";
declare const Engine: ComponentType<ImageFlyInProps>;
export default Engine;
